// pingLoop periodically pings all endpoints to measure latency.
func (bc *ServiceManager) pingLoop(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-bc.ctx.Done():
			return
		case <-ticker.C:
			for _, ec := range bc.endpoints {
				if ec.conn == nil {
					continue
				}
				pingCtx, cancel := context.WithTimeout(bc.ctx, 5*time.Second)
				if err := ec.ping(pingCtx); err != nil {
					zap.L().Debug("Ping failed",
						zap.String("endpoint", ec.target),
						zap.Error(err))
				}
				cancel()
			}
		}
	}
}

// rebalanceLoop periodically re-evaluates which endpoint should be active.
func (bc *ServiceManager) rebalanceLoop(interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-bc.ctx.Done():
			return
		case <-ticker.C:
			bc.selectActive()
		}
	}
}

// startLogStream subscribes to the BackendService.Log stream on the active connection.
func (bc *ServiceManager) startLogStream() {
	logCtx, logCancel := context.WithCancel(bc.ctx)
	bc.logCancel = logCancel

	conn := bc.ActiveConn()
	if conn == nil {
		return
	}
	client := serviceconfig_pb.NewBackendServiceClient(conn)
	stream, err := client.Log(logCtx, &emptypb.Empty{})
	if err != nil {
		zap.L().Debug("Failed to start Log stream", zap.Error(err))
		return
	}

	go func() {
		l := zap.L().With(zap.String("source", "backend"))
		for {
			msg, err := stream.Recv()
			if err != nil {
				if err != io.EOF && logCtx.Err() == nil {
					l.Debug("Log stream ended", zap.Error(err))
				}
				return
			}
			text := msg.GetMessage()
			switch msg.GetLevel() {
			case logger_pb.Level_LEVEL_TRACE, logger_pb.Level_LEVEL_DEBUG:
				l.Debug(text)
			case logger_pb.Level_LEVEL_INFO:
				l.Info(text)
			case logger_pb.Level_LEVEL_WARN:
				l.Warn(text)
			case logger_pb.Level_LEVEL_ERROR:
				l.Error(text)
			default:
				l.Info(text)
			}
		}
	}()
}

// startSubscribe subscribes to the BackendService.Subscribe stream on the active connection.
func (bc *ServiceManager) startSubscribe() {
	subCtx, subCancel := context.WithCancel(bc.ctx)
	bc.subCancel = subCancel

	conn := bc.ActiveConn()
	if conn == nil {
		return
	}
	client := serviceconfig_pb.NewBackendServiceClient(conn)
	stream, err := client.Subscribe(subCtx, &emptypb.Empty{})
	if err != nil {
		zap.L().Debug("Failed to start Subscribe stream", zap.Error(err))
		return
	}

	go func() {
		for {
			state, err := stream.Recv()
			if err != nil {
				if err != io.EOF && subCtx.Err() == nil {
					zap.L().Debug("Subscribe stream ended", zap.Error(err))
				}
				return
			}
			zap.L().Info("Received cluster state update",
				zap.Int("clusters", len(state.GetClusters())))
			// Re-evaluate active connection based on new topology
			bc.selectActive()
		}
	}()
}

// startWatchJwks subscribes to the BackendService.WatchJwks stream and keeps
// the local JWK cache up to date. The cache is used by VerifyToken to validate
// inbound service tokens without calling the backend on every request.
func (bc *ServiceManager) startWatchJwks() {
	jwkCtx, jwkCancel := context.WithCancel(bc.ctx)
	bc.jwkCancel = jwkCancel

	conn := bc.ActiveConn()
	if conn == nil {
		return
	}
	client := serviceconfig_pb.NewBackendServiceClient(conn)
	stream, err := client.WatchJwks(jwkCtx, &emptypb.Empty{})
	if err != nil {
		zap.L().Debug("Failed to start WatchJwks stream", zap.Error(err))
		return
	}

	go func() {
		for {
			jwks, err := stream.Recv()
			if err != nil {
				if err != io.EOF && jwkCtx.Err() == nil {
					zap.L().Debug("WatchJwks stream ended", zap.Error(err))
				}
				return
			}
			bc.jwkMu.Lock()
			bc.jwkCache = jwks.GetKeys()
			bc.jwkMu.Unlock()
			zap.L().Info("JWKS cache updated", zap.Int("keys", len(jwks.GetKeys())))
		}
	}()
}

// ---------------------------------------------------------------------------
// Token verification
// ---------------------------------------------------------------------------

// VerifyToken parses and validates a JWT token string using the cached JWKS.
// It extracts the kid from the JWT header, finds the matching key in the cache,
// verifies the signature, and validates exp/iat claims.
// Returns the parsed token on success.
func (bc *ServiceManager) VerifyToken(tokenString string) (*wrapperToken.TokenWrapper, error) {
	tok, err := wrapperToken.ParseToken(tokenString)
	if err != nil {
		return nil, fmt.Errorf("parsing token: %w", err)
	}

	kid := tok.GetKid()
	if kid == "" {
		return nil, fmt.Errorf("JWT missing kid in header")
	}

	bc.jwkMu.RLock()
	var matchingKey *jwk_pb.Jwk
	for _, k := range bc.jwkCache {
		if k.GetKid() == kid {
			matchingKey = k
			break
		}
	}
	bc.jwkMu.RUnlock()

	if matchingKey == nil {
		return nil, fmt.Errorf("no matching key found for kid %q", kid)
	}

	immJwk, err := wrapperJwk.NewImmutableJwk(matchingKey)
	if err != nil {
		return nil, fmt.Errorf("creating immutable JWK: %w", err)
	}

	if err := tok.Verify(immJwk); err != nil {
		return nil, fmt.Errorf("token verification failed: %w", err)
	}

	return tok, nil
}

// ---------------------------------------------------------------------------
// gRPC server interceptors
// ---------------------------------------------------------------------------

// AuthUnaryInterceptor returns a gRPC unary server interceptor that validates
// inbound Bearer tokens. Returns codes.Unauthenticated on missing/invalid tokens.
func (bc *ServiceManager) AuthUnaryInterceptor() grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		tokenStr, err := extractBearerToken(ctx)
		if err != nil {
			return nil, status.Errorf(codes.Unauthenticated, "missing authorization: %v", err)
		}
		tok, err := bc.VerifyToken(tokenStr)
		if err != nil {
			return nil, status.Errorf(codes.Unauthenticated, "invalid token: %v", err)
		}
		ctx = context.WithValue(ctx, tokenContextKey{}, tok)
		return handler(ctx, req)
	}
}

// AuthStreamInterceptor returns a gRPC stream server interceptor that validates
// inbound Bearer tokens.
func (bc *ServiceManager) AuthStreamInterceptor() grpc.StreamServerInterceptor {
	return func(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
		tokenStr, err := extractBearerToken(ss.Context())
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "missing authorization: %v", err)
		}
		tok, err := bc.VerifyToken(tokenStr)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid token: %v", err)
		}
		ctx := context.WithValue(ss.Context(), tokenContextKey{}, tok)
		return handler(srv, &wrappedServerStream{ServerStream: ss, ctx: ctx})
	}
}

// ---------------------------------------------------------------------------
// HTTP middleware
// ---------------------------------------------------------------------------

// AuthHTTPMiddleware returns an HTTP middleware that validates inbound Bearer
// tokens using the request path as the method.
// Requests to exempt paths bypass authentication entirely.
// On auth failure: 401 for missing/invalid token.
// The verified token is stored in the request context (use TokenFromContext).
func (bc *ServiceManager) AuthHTTPMiddleware(exemptPaths ...string) func(http.Handler) http.Handler {
	exempt := make(map[string]bool, len(exemptPaths))
	for _, p := range exemptPaths {
		exempt[p] = true
	}
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if exempt[r.URL.Path] {
				next.ServeHTTP(w, r)
				return
			}
			auth := r.Header.Get("Authorization")
			if !strings.HasPrefix(auth, "Bearer ") {
				http.Error(w, "missing or invalid Authorization header", http.StatusUnauthorized)
				return
			}
			tokenStr := strings.TrimPrefix(auth, "Bearer ")
			tok, err := bc.VerifyToken(tokenStr)
			if err != nil {
				http.Error(w, "invalid token: "+err.Error(), http.StatusUnauthorized)
				return
			}
			ctx := context.WithValue(r.Context(), tokenContextKey{}, tok)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// ---------------------------------------------------------------------------
// Context helpers
// ---------------------------------------------------------------------------

// tokenContextKey is the context key for storing the verified token.
type tokenContextKey struct{}

// TokenFromContext extracts the verified token from the context.
// Returns nil if no token is present (e.g., unauthenticated context).
func TokenFromContext(ctx context.Context) *wrapperToken.TokenWrapper {
	tok, _ := ctx.Value(tokenContextKey{}).(*wrapperToken.TokenWrapper)
	return tok
}

// wrappedServerStream wraps grpc.ServerStream to override the context.
type wrappedServerStream struct {
	grpc.ServerStream
	ctx context.Context
}

func (w *wrappedServerStream) Context() context.Context { return w.ctx }

// extractBearerToken extracts the Bearer token from gRPC metadata.
func extractBearerToken(ctx context.Context) (string, error) {
	md, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return "", fmt.Errorf("no metadata in context")
	}
	vals := md.Get("authorization")
	if len(vals) == 0 {
		return "", fmt.Errorf("no authorization header")
	}
	auth := vals[0]
	if !strings.HasPrefix(auth, "Bearer ") {
		return "", fmt.Errorf("authorization header is not Bearer")
	}
	return strings.TrimPrefix(auth, "Bearer "), nil
}

// closeAll closes all endpoint connections.
func (bc *ServiceManager) closeAll() error {
	var firstErr error
	for _, ec := range bc.endpoints {
		if err := ec.close(); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// ---------------------------------------------------------------------------
// Token exchange interceptors (private_key auth)
// ---------------------------------------------------------------------------

// tokenMinter handles the CredPair token exchange flow:
//  1. Mints a short-lived throwaway JWT signed with the CredPair private key
//  2. Exchanges it via TokenExchangerService for a refresh token (Phase 1)
//  3. Exchanges the refresh token for a service token with the correct audience (Phase 2)
//  4. Caches and refreshes the service token before expiry
type tokenMinter struct {
	key        *wrapperKey.ImmutableKey
	mu         sync.Mutex
	current    string    // cached service token base64
	exp        time.Time // expiry of cached token
	instanceId string    // instance_id from token exchange (set by server)
	exchClient backend_svc_pb.TokenExchangerServiceClient
}

// newTokenMinter creates a tokenMinter from a private key.
func newTokenMinter(privateKey *key_pb.Key) (*tokenMinter, error) {
	if privateKey == nil {
		return nil, fmt.Errorf("private_key is required for authenticated backend connections")
	}
	immKey, err := wrapperKey.NewImmutableKey(privateKey)
	if err != nil {
		return nil, fmt.Errorf("parsing private key: %w", err)
	}
	return &tokenMinter{key: immKey}, nil
}

// setConn sets the gRPC connection for token exchange.
// Must be called after the connection is created.
func (tm *tokenMinter) setConn(conn *grpc.ClientConn) {
	tm.exchClient = backend_svc_pb.NewTokenExchangerServiceClient(conn)
}

// getToken returns a valid bearer token, performing token exchange if the
// cached token is expired or about to expire.
func (tm *tokenMinter) getToken() (string, error) {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	// Return cached token if still valid (with refresh buffer)
	if tm.current != "" && time.Now().Add(tokenRefreshBuffer).Before(tm.exp) {
		return tm.current, nil
	}
	return tm.doExchange()
}

// invalidate clears the cached token, forcing the next getToken to re-exchange.
func (tm *tokenMinter) invalidate() {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	tm.current = ""
	tm.exp = time.Time{}
}

// doExchange performs the full two-phase token exchange. Must be called with tm.mu held.
func (tm *tokenMinter) doExchange() (string, error) {
	// 1. Mint a throwaway JWT signed with the CredPair private key.
	//    Claims don't matter — TokenExchanger determines identity from CredPair lookup by kid.
	now := time.Now()
	expTime := now.Add(tokenLifetime)
	tok := wrapperToken.NewImmutableToken(nil)
	tok.SetIssuer("backendclient").
		SetSubject("backendclient").
		SetAudience("backend").
		SetIssuedAt(now.Unix()).
		SetExpiration(expTime.Unix())
	if err := tok.Sign(tm.key); err != nil {
		return "", fmt.Errorf("signing throwaway token: %w", err)
	}
	throwaway := tok.GetBase64()

	if tm.exchClient == nil {
		return "", fmt.Errorf("token exchange client not initialized")
	}

	// 2. Phase 1: Exchange throwaway JWT for a refresh token.
	exchCtx1, cancel1 := context.WithTimeout(context.Background(), exchangeTimeout)
	defer cancel1()
	refreshResp, err := tm.exchClient.ExchangeToken(exchCtx1, &backend_svc_pb.TokenRequest{
		InputToken: throwaway,
	})
	if err != nil {
		return "", fmt.Errorf("token exchange phase 1 (external→refresh): %w", err)
	}

	// 3. Phase 2: Exchange refresh token for a service token with the correct audience.
	exchCtx2, cancel2 := context.WithTimeout(context.Background(), exchangeTimeout)
	defer cancel2()
	serviceResp, err := tm.exchClient.ExchangeToken(exchCtx2, &backend_svc_pb.TokenRequest{
		InputToken: refreshResp.GetBase64(),
		Aud:        serviceAudience,
	})
	if err != nil {
		return "", fmt.Errorf("token exchange phase 2 (refresh→service): %w", err)
	}

	// 4. Cache the service token and parse its expiry + instance_id from the payload.
	tm.current = serviceResp.GetBase64()
	if payload := serviceResp.GetPayload(); payload != nil {
		if fields := payload.GetFields(); fields != nil {
			if expVal, ok := fields["exp"]; ok && expVal != nil {
				tm.exp = time.Unix(int64(expVal.GetNumberValue()), 0)
			}
			// Extract instance_id (assigned by TokenExchanger on first exchange)
			if idVal, ok := fields["instance_id"]; ok && idVal != nil {
				tm.instanceId = idVal.GetStringValue()
			}
		}
	}
	if tm.exp.IsZero() || tm.exp.Before(time.Now()) {
		tm.exp = time.Now().Add(time.Hour) // fallback: 1 hour
	}

	return tm.current, nil
}

// minterUnaryInterceptor returns a gRPC unary client interceptor that
// attaches the cached service token to every outgoing call.
// TokenExchanger calls are skipped (they don't require authentication).
func minterUnaryInterceptor(minter *tokenMinter) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply interface{},
		cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		// Skip auth for TokenExchanger calls to prevent recursion
		if strings.Contains(method, "TokenExchangerService") {
			return invoker(ctx, method, req, reply, cc, opts...)
		}
		token, err := minter.getToken()
		if err != nil {
			return fmt.Errorf("obtaining bearer token: %w", err)
		}
		ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token)
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

// minterStreamInterceptor returns a gRPC stream client interceptor that
// attaches the cached service token to every outgoing stream.
// TokenExchanger calls are skipped (they don't require authentication).
func minterStreamInterceptor(minter *tokenMinter) grpc.StreamClientInterceptor {
	return func(ctx context.Context, desc *grpc.StreamDesc, cc *grpc.ClientConn,
		method string, streamer grpc.Streamer, opts ...grpc.CallOption) (grpc.ClientStream, error) {
		// Skip auth for TokenExchanger calls to prevent recursion
		if strings.Contains(method, "TokenExchangerService") {
			return streamer(ctx, desc, cc, method, opts...)
		}
		token, err := minter.getToken()
		if err != nil {
			return nil, fmt.Errorf("obtaining bearer token: %w", err)
		}
		ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token)
		return streamer(ctx, desc, cc, method, opts...)
	}
}

// ---------------------------------------------------------------------------
// Cloud-native identity detection
// ---------------------------------------------------------------------------

// imdsTimeout is the timeout for cloud metadata service probes.
const imdsTimeout = 2 * time.Second

// detectCloud probes cloud metadata endpoints to determine which cloud
// environment the process is running in. Only uses metadata service
// endpoints — never reads ~/.aws, env credentials, or other human-user
// credential sources.
func detectCloud(ctx context.Context) (cloudvendor_pb.CloudVendor, error) {
	httpClient := &http.Client{Timeout: imdsTimeout}

	// 1. GCP: metadata server with Google-specific header
	if req, err := http.NewRequestWithContext(ctx, "GET", "http://169.254.169.254/", nil); err == nil {
		req.Header.Set("Metadata-Flavor", "Google")
		if resp, err := httpClient.Do(req); err == nil {
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				if resp.Header.Get("Metadata-Flavor") == "Google" {
					return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_GCP, nil
				}
			}
		}
	}

	// 2. Azure: instance metadata with Azure-specific header
	if req, err := http.NewRequestWithContext(ctx, "GET",
		"http://169.254.169.254/metadata/instance?api-version=2021-02-01", nil); err == nil {
		req.Header.Set("Metadata", "true")
		if resp, err := httpClient.Do(req); err == nil {
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AZURE, nil
			}
		}
	}

	// 3. AWS: IMDSv2 session token (preferred) or IMDSv1 fallback
	if req, err := http.NewRequestWithContext(ctx, "PUT",
		"http://169.254.169.254/latest/api/token", nil); err == nil {
		req.Header.Set("X-aws-ec2-metadata-token-ttl-seconds", "21600")
		if resp, err := httpClient.Do(req); err == nil {
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AWS, nil
			}
		}
	}
	// IMDSv1 fallback
	if req, err := http.NewRequestWithContext(ctx, "GET",
		"http://169.254.169.254/latest/meta-data/", nil); err == nil {
		if resp, err := httpClient.Do(req); err == nil {
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AWS, nil
			}
		}
	}

	// 4. AWS EKS IRSA: projected service account token
	if os.Getenv("AWS_WEB_IDENTITY_TOKEN_FILE") != "" {
		return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AWS, nil
	}

	return cloudvendor_pb.CloudVendor_CLOUD_VENDOR_UNDEFINED,
		fmt.Errorf("no cloud metadata service detected (tried GCP, Azure, AWS)")
}

// ---------------------------------------------------------------------------
// AWS SigV4 signing (no SDK)
// ---------------------------------------------------------------------------

// awsIMDSCredentials fetches IAM role credentials from the EC2 Instance
// Metadata Service (IMDSv2). Returns access key, secret key, and session token.
func awsIMDSCredentials(ctx context.Context) (accessKey, secretKey, sessionToken string, err error) {
	httpClient := &http.Client{Timeout: imdsTimeout}

	// Get IMDSv2 session token
	tokenReq, err := http.NewRequestWithContext(ctx, "PUT",
		"http://169.254.169.254/latest/api/token", nil)
	if err != nil {
		return "", "", "", fmt.Errorf("creating IMDS token request: %w", err)
	}
	tokenReq.Header.Set("X-aws-ec2-metadata-token-ttl-seconds", "21600")
	tokenResp, err := httpClient.Do(tokenReq)
	if err != nil {
		return "", "", "", fmt.Errorf("fetching IMDS token: %w", err)
	}
	tokenBody, _ := io.ReadAll(tokenResp.Body)
	tokenResp.Body.Close()
	imdsToken := string(tokenBody)

	// Get IAM role name
	roleReq, err := http.NewRequestWithContext(ctx, "GET",
		"http://169.254.169.254/latest/meta-data/iam/security-credentials/", nil)
	if err != nil {
		return "", "", "", fmt.Errorf("creating role request: %w", err)
	}
	roleReq.Header.Set("X-aws-ec2-metadata-token", imdsToken)
	roleResp, err := httpClient.Do(roleReq)
	if err != nil {
		return "", "", "", fmt.Errorf("fetching IAM role: %w", err)
	}
	roleBody, _ := io.ReadAll(roleResp.Body)
	roleResp.Body.Close()
	roleName := strings.TrimSpace(string(roleBody))
	if roleName == "" {
		return "", "", "", fmt.Errorf("no IAM role attached to instance")
	}

	// Get credentials for the role
	credReq, err := http.NewRequestWithContext(ctx, "GET",
		"http://169.254.169.254/latest/meta-data/iam/security-credentials/"+roleName, nil)
	if err != nil {
		return "", "", "", fmt.Errorf("creating credentials request: %w", err)
	}
	credReq.Header.Set("X-aws-ec2-metadata-token", imdsToken)
	credResp, err := httpClient.Do(credReq)
	if err != nil {
		return "", "", "", fmt.Errorf("fetching credentials: %w", err)
	}
	credBody, _ := io.ReadAll(credResp.Body)
	credResp.Body.Close()

	// Parse JSON credentials (simple extraction without encoding/json)
	credStr := string(credBody)
	accessKey = extractJSONString(credStr, "AccessKeyId")
	secretKey = extractJSONString(credStr, "SecretAccessKey")
	sessionToken = extractJSONString(credStr, "Token")
	if accessKey == "" || secretKey == "" {
		return "", "", "", fmt.Errorf("failed to parse IMDS credentials")
	}
	return accessKey, secretKey, sessionToken, nil
}

// awsEKSCredentials reads credentials from EKS IRSA (projected service account token)
// and fetches temporary credentials via STS AssumeRoleWithWebIdentity.
func awsEKSCredentials(ctx context.Context) (accessKey, secretKey, sessionToken string, err error) {
	tokenFile := os.Getenv("AWS_WEB_IDENTITY_TOKEN_FILE")
	roleArn := os.Getenv("AWS_ROLE_ARN")
	if tokenFile == "" || roleArn == "" {
		return "", "", "", fmt.Errorf("AWS_WEB_IDENTITY_TOKEN_FILE or AWS_ROLE_ARN not set")
	}
	tokenBytes, err := os.ReadFile(tokenFile)
	if err != nil {
		return "", "", "", fmt.Errorf("reading web identity token: %w", err)
	}
	webToken := strings.TrimSpace(string(tokenBytes))

	region := os.Getenv("AWS_REGION")
	if region == "" {
		region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = "us-east-1"
	}

	// Call STS AssumeRoleWithWebIdentity
	stsURL := fmt.Sprintf("https://sts.%s.amazonaws.com/", region)
	body := url.Values{
		"Action":           {"AssumeRoleWithWebIdentity"},
		"Version":          {"2011-06-15"},
		"RoleArn":          {roleArn},
		"RoleSessionName":  {"servicemanager"},
		"WebIdentityToken": {webToken},
	}.Encode()

	httpClient := &http.Client{Timeout: 10 * time.Second}
	req, err := http.NewRequestWithContext(ctx, "POST", stsURL, strings.NewReader(body))
	if err != nil {
		return "", "", "", fmt.Errorf("creating STS request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	resp, err := httpClient.Do(req)
	if err != nil {
		return "", "", "", fmt.Errorf("STS AssumeRoleWithWebIdentity: %w", err)
	}
	respBody, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	respStr := string(respBody)

	accessKey = extractXMLValue(respStr, "AccessKeyId")
	secretKey = extractXMLValue(respStr, "SecretAccessKey")
	sessionToken = extractXMLValue(respStr, "SessionToken")
	if accessKey == "" || secretKey == "" {
		return "", "", "", fmt.Errorf("failed to parse STS AssumeRoleWithWebIdentity response")
	}
	return accessKey, secretKey, sessionToken, nil
}

// awsSignV4 signs an HTTP request using AWS Signature Version 4.
// Returns the signed headers map (including Authorization).
func awsSignV4(method, urlStr, body, accessKey, secretKey, sessionToken, region, service string, now time.Time) (map[string]string, error) {
	u, err := url.Parse(urlStr)
	if err != nil {
		return nil, fmt.Errorf("parsing URL: %w", err)
	}

	// Dates
	datestamp := now.UTC().Format("20060102")
	amzDate := now.UTC().Format("20060102T150405Z")

	// Payload hash
	payloadHash := sha256Hex(body)

	// Headers to sign
	headers := map[string]string{
		"host":                 u.Host,
		"x-amz-date":           amzDate,
		"x-amz-content-sha256": payloadHash,
		"content-type":         "application/x-www-form-urlencoded; charset=utf-8",
	}
	if sessionToken != "" {
		headers["x-amz-security-token"] = sessionToken
	}

	// Sorted header names
	var signedHeaderNames []string
	for k := range headers {
		signedHeaderNames = append(signedHeaderNames, k)
	}
	sort.Strings(signedHeaderNames)
	signedHeaders := strings.Join(signedHeaderNames, ";")

	// Canonical headers
	var canonicalHeaders strings.Builder
	for _, k := range signedHeaderNames {
		canonicalHeaders.WriteString(k)
		canonicalHeaders.WriteString(":")
		canonicalHeaders.WriteString(strings.TrimSpace(headers[k]))
		canonicalHeaders.WriteString("\n")
	}

	// Canonical request
	canonicalRequest := strings.Join([]string{
		method,
		u.Path,
		u.RawQuery,
		canonicalHeaders.String(),
		signedHeaders,
		payloadHash,
	}, "\n")

	// Credential scope
	credentialScope := strings.Join([]string{datestamp, region, service, "aws4_request"}, "/")

	// String to sign
	stringToSign := strings.Join([]string{
		"AWS4-HMAC-SHA256",
		amzDate,
		credentialScope,
		sha256Hex(canonicalRequest),
	}, "\n")

	// Signing key derivation
	signingKey := hmacSHA256(
		hmacSHA256(
			hmacSHA256(
				hmacSHA256([]byte("AWS4"+secretKey), []byte(datestamp)),
				[]byte(region),
			),
			[]byte(service),
		),
		[]byte("aws4_request"),
	)

	// Signature
	signature := hex.EncodeToString(hmacSHA256(signingKey, []byte(stringToSign)))

	// Authorization header
	authHeader := fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		accessKey, credentialScope, signedHeaders, signature)

	result := make(map[string]string)
	for k, v := range headers {
		result[k] = v
	}
	result["authorization"] = authHeader

	return result, nil
}

// sha256Hex returns the lowercase hex SHA256 digest of s.
func sha256Hex(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// hmacSHA256 returns the HMAC-SHA256 of data using key.
func hmacSHA256(key, data []byte) []byte {
	h := hmac.New(sha256.New, key)
	h.Write(data)
	return h.Sum(nil)
}

// extractJSONString extracts a string value from a simple JSON object by key.
// This avoids importing encoding/json for a trivial extraction.
func extractJSONString(json, key string) string {
	needle := `"` + key + `"`
	idx := strings.Index(json, needle)
	if idx < 0 {
		return ""
	}
	rest := json[idx+len(needle):]
	// Skip : and whitespace
	rest = strings.TrimLeft(rest, " \t\n\r:")
	if len(rest) == 0 || rest[0] != '"' {
		return ""
	}
	rest = rest[1:]
	end := strings.IndexByte(rest, '"')
	if end < 0 {
		return ""
	}
	return rest[:end]
}

// extractXMLValue extracts a value between XML tags <key>value</key>.
func extractXMLValue(xml, key string) string {
	start := "<" + key + ">"
	end := "</" + key + ">"
	idx := strings.Index(xml, start)
	if idx < 0 {
		return ""
	}
	rest := xml[idx+len(start):]
	endIdx := strings.Index(rest, end)
	if endIdx < 0 {
		return ""
	}
	return rest[:endIdx]
}

// buildAWSCloudProof creates a CloudIdentityProof with a presigned STS
// GetCallerIdentity request signed using AWS SigV4.
func buildAWSCloudProof(ctx context.Context) (*cloudidentity_pb.CloudIdentityProof, error) {
	// Try EKS IRSA first, then IMDS
	var accessKey, secretKey, sessionToken string
	var err error
	if os.Getenv("AWS_WEB_IDENTITY_TOKEN_FILE") != "" {
		accessKey, secretKey, sessionToken, err = awsEKSCredentials(ctx)
	} else {
		accessKey, secretKey, sessionToken, err = awsIMDSCredentials(ctx)
	}
	if err != nil {
		return nil, fmt.Errorf("obtaining AWS credentials: %w", err)
	}

	region := os.Getenv("AWS_REGION")
	if region == "" {
		region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = "us-east-1"
	}

	stsURL := fmt.Sprintf("https://sts.%s.amazonaws.com/", region)
	body := "Action=GetCallerIdentity&Version=2011-06-15"
	now := time.Now()

	signedHeaders, err := awsSignV4("POST", stsURL, body, accessKey, secretKey, sessionToken, region, "sts", now)
	if err != nil {
		return nil, fmt.Errorf("signing STS request: %w", err)
	}

	return &cloudidentity_pb.CloudIdentityProof{
		Vendor: cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AWS,
		PresignedRequest: &cloudidentity_pb.PresignedHttpRequest{
			Method:  "POST",
			Url:     stsURL,
			Headers: signedHeaders,
			Body:    body,
		},
	}, nil
}

// buildGCPCloudProof fetches an identity token from the GCP metadata server.
func buildGCPCloudProof(ctx context.Context, audience string) (*cloudidentity_pb.CloudIdentityProof, error) {
	metadataURL := fmt.Sprintf(
		"http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity?audience=%s&format=full",
		url.QueryEscape(audience))

	req, err := http.NewRequestWithContext(ctx, "GET", metadataURL, nil)
	if err != nil {
		return nil, fmt.Errorf("creating GCP metadata request: %w", err)
	}
	req.Header.Set("Metadata-Flavor", "Google")

	httpClient := &http.Client{Timeout: 5 * time.Second}
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("fetching GCP identity token: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("GCP metadata returned %d: %s", resp.StatusCode, string(body))
	}

	return &cloudidentity_pb.CloudIdentityProof{
		Vendor:        cloudvendor_pb.CloudVendor_CLOUD_VENDOR_GCP,
		IdentityToken: strings.TrimSpace(string(body)),
	}, nil
}

// buildAzureCloudProof fetches a managed identity token from the Azure IMDS.
func buildAzureCloudProof(ctx context.Context, resource string) (*cloudidentity_pb.CloudIdentityProof, error) {
	metadataURL := fmt.Sprintf(
		"http://169.254.169.254/metadata/identity/oauth2/token?api-version=2018-02-01&resource=%s",
		url.QueryEscape(resource))

	req, err := http.NewRequestWithContext(ctx, "GET", metadataURL, nil)
	if err != nil {
		return nil, fmt.Errorf("creating Azure IMDS request: %w", err)
	}
	req.Header.Set("Metadata", "true")

	httpClient := &http.Client{Timeout: 5 * time.Second}
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("fetching Azure managed identity token: %w", err)
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("Azure IMDS returned %d: %s", resp.StatusCode, string(body))
	}

	// Extract access_token from JSON response
	token := extractJSONString(string(body), "access_token")
	if token == "" {
		return nil, fmt.Errorf("Azure IMDS response missing access_token")
	}

	return &cloudidentity_pb.CloudIdentityProof{
		Vendor:        cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AZURE,
		IdentityToken: token,
	}, nil
}

// ---------------------------------------------------------------------------
// cloudTokenMinter — cloud-native token exchange
// ---------------------------------------------------------------------------

// cloudTokenMinter handles cloud-native token exchange:
//  1. Builds a CloudIdentityProof (AWS presigned STS / GCP identity token / Azure managed identity)
//  2. Sends it to TokenExchangerService.ExchangeToken to get a refresh token
//  3. Exchanges the refresh token for an access token with the correct audience
//  4. Caches and refreshes using half-life randomized renewal
type cloudTokenMinter struct {
	vendor      cloudvendor_pb.CloudVendor
	serviceId   string // from config's instance_id
	mu          sync.Mutex
	current     string    // cached access token base64
	exp         time.Time // expiry of cached access token
	refreshTok  string    // cached refresh token base64
	refreshExp  time.Time // expiry of refresh token
	refreshIat  time.Time // issued-at of refresh token
	instanceId  string    // server-assigned instance_id
	exchClient  backend_svc_pb.TokenExchangerServiceClient
	cancelRenew context.CancelFunc
}

// newCloudTokenMinter creates a cloudTokenMinter for the detected vendor.
func newCloudTokenMinter(vendor cloudvendor_pb.CloudVendor, serviceId string) *cloudTokenMinter {
	return &cloudTokenMinter{
		vendor:    vendor,
		serviceId: serviceId,
	}
}

// setConn sets the gRPC connection for token exchange.
func (cm *cloudTokenMinter) setConn(conn *grpc.ClientConn) {
	cm.exchClient = backend_svc_pb.NewTokenExchangerServiceClient(conn)
}

// getToken returns a valid bearer token. Performs token exchange if needed.
func (cm *cloudTokenMinter) getToken() (string, error) {
	cm.mu.Lock()
	defer cm.mu.Unlock()

	// Return cached access token if still valid
	if cm.current != "" && time.Now().Add(tokenRefreshBuffer).Before(cm.exp) {
		return cm.current, nil
	}

	// Try refresh → access exchange if we have a valid refresh token
	if cm.refreshTok != "" && time.Now().Before(cm.refreshExp) {
		tok, err := cm.doAccessExchange()
		if err == nil {
			return tok, nil
		}
		zap.L().Warn("Cloud auth: refresh→access exchange failed, re-proving", zap.Error(err))
	}

	// Full cloud proof exchange
	if err := cm.doCloudExchange(); err != nil {
		return "", fmt.Errorf("cloud token exchange: %w", err)
	}
	return cm.doAccessExchange()
}

// invalidate clears cached tokens, forcing re-exchange.
func (cm *cloudTokenMinter) invalidate() {
	cm.mu.Lock()
	defer cm.mu.Unlock()
	cm.current = ""
	cm.exp = time.Time{}
	cm.refreshTok = ""
	cm.refreshExp = time.Time{}
}

// doCloudExchange builds a cloud proof and exchanges it for a refresh token.
// Must be called with cm.mu held.
func (cm *cloudTokenMinter) doCloudExchange() error {
	proof, err := cm.buildProof()
	if err != nil {
		return fmt.Errorf("building cloud proof: %w", err)
	}

	if cm.exchClient == nil {
		return fmt.Errorf("token exchange client not initialized")
	}

	req := &backend_svc_pb.TokenRequest{
		CloudProof: proof,
	}
	// If we have an unexpired refresh token, include it as continuity_token
	if cm.refreshTok != "" && time.Now().Before(cm.refreshExp) {
		req.ContinuityToken = cm.refreshTok
	}

	exchCtx, cancel := context.WithTimeout(context.Background(), exchangeTimeout)
	defer cancel()
	resp, err := cm.exchClient.ExchangeToken(exchCtx, req)
	if err != nil {
		return fmt.Errorf("cloud proof exchange: %w", err)
	}

	cm.refreshTok = resp.GetBase64()
	cm.refreshIat = time.Now()
	if payload := resp.GetPayload(); payload != nil {
		if fields := payload.GetFields(); fields != nil {
			if expVal, ok := fields["exp"]; ok && expVal != nil {
				cm.refreshExp = time.Unix(int64(expVal.GetNumberValue()), 0)
			}
			if idVal, ok := fields["instance_id"]; ok && idVal != nil {
				cm.instanceId = idVal.GetStringValue()
			}
		}
	}
	if cm.refreshExp.IsZero() || cm.refreshExp.Before(time.Now()) {
		cm.refreshExp = time.Now().Add(24 * time.Hour) // fallback
	}

	// Schedule half-life renewal
	cm.scheduleRenewal()

	return nil
}

// doAccessExchange exchanges the cached refresh token for an access token.
// Must be called with cm.mu held.
func (cm *cloudTokenMinter) doAccessExchange() (string, error) {
	if cm.exchClient == nil {
		return "", fmt.Errorf("token exchange client not initialized")
	}

	exchCtx, cancel := context.WithTimeout(context.Background(), exchangeTimeout)
	defer cancel()
	resp, err := cm.exchClient.ExchangeToken(exchCtx, &backend_svc_pb.TokenRequest{
		InputToken: cm.refreshTok,
		Aud:        serviceAudience,
	})
	if err != nil {
		return "", fmt.Errorf("refresh→access exchange: %w", err)
	}

	cm.current = resp.GetBase64()
	if payload := resp.GetPayload(); payload != nil {
		if fields := payload.GetFields(); fields != nil {
			if expVal, ok := fields["exp"]; ok && expVal != nil {
				cm.exp = time.Unix(int64(expVal.GetNumberValue()), 0)
			}
			if idVal, ok := fields["instance_id"]; ok && idVal != nil {
				cm.instanceId = idVal.GetStringValue()
			}
		}
	}
	if cm.exp.IsZero() || cm.exp.Before(time.Now()) {
		cm.exp = time.Now().Add(time.Hour) // fallback
	}

	return cm.current, nil
}

// buildProof constructs a CloudIdentityProof appropriate for the vendor.
func (cm *cloudTokenMinter) buildProof() (*cloudidentity_pb.CloudIdentityProof, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	switch cm.vendor {
	case cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AWS:
		return buildAWSCloudProof(ctx)
	case cloudvendor_pb.CloudVendor_CLOUD_VENDOR_GCP:
		return buildGCPCloudProof(ctx, serviceAudience)
	case cloudvendor_pb.CloudVendor_CLOUD_VENDOR_AZURE:
		return buildAzureCloudProof(ctx, serviceAudience)
	default:
		return nil, fmt.Errorf("unsupported cloud vendor: %s", cm.vendor.String())
	}
}

// scheduleRenewal starts a background goroutine that renews the refresh token
// at a randomized time after its half-life. This prevents all instances from
// renewing simultaneously and makes it harder for hostile processes to predict
// when tokens will be refreshed.
func (cm *cloudTokenMinter) scheduleRenewal() {
	// Cancel any previous renewal goroutine
	if cm.cancelRenew != nil {
		cm.cancelRenew()
	}

	ctx, cancel := context.WithCancel(context.Background())
	cm.cancelRenew = cancel

	halfLife := cm.refreshExp.Sub(cm.refreshIat) / 2
	if halfLife <= 0 {
		halfLife = 12 * time.Hour
	}
	// Renew at: issued_at + half_life + random(0, half_life)
	jitter := randomDuration(halfLife)
	renewAt := cm.refreshIat.Add(halfLife + jitter)

	go func() {
		timer := time.NewTimer(time.Until(renewAt))
		defer timer.Stop()
		select {
		case <-ctx.Done():
			return
		case <-timer.C:
			cm.mu.Lock()
			defer cm.mu.Unlock()
			if err := cm.doCloudExchange(); err != nil {
				zap.L().Warn("Cloud auth: half-life renewal failed", zap.Error(err))
			} else {
				zap.L().Info("Cloud auth: refresh token renewed at half-life")
			}
		}
	}()
}

// randomDuration returns a random duration in [0, max).
func randomDuration(max time.Duration) time.Duration {
	if max <= 0 {
		return 0
	}
	n, err := crand.Int(crand.Reader, big.NewInt(int64(max)))
	if err != nil {
		return max / 2 // fallback to deterministic midpoint
	}
	return time.Duration(n.Int64())
}

// cloudMinterUnaryInterceptor returns a gRPC unary client interceptor that
// attaches the cloud-exchanged service token to every outgoing call.
func cloudMinterUnaryInterceptor(minter *cloudTokenMinter) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply interface{},
		cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		if strings.Contains(method, "TokenExchangerService") {
			return invoker(ctx, method, req, reply, cc, opts...)
		}
		token, err := minter.getToken()
		if err != nil {
			return fmt.Errorf("obtaining bearer token: %w", err)
		}
		ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token)
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

// cloudMinterStreamInterceptor returns a gRPC stream client interceptor that
// attaches the cloud-exchanged service token to every outgoing stream.
func cloudMinterStreamInterceptor(minter *cloudTokenMinter) grpc.StreamClientInterceptor {
	return func(ctx context.Context, desc *grpc.StreamDesc, cc *grpc.ClientConn,
		method string, streamer grpc.Streamer, opts ...grpc.CallOption) (grpc.ClientStream, error) {
		if strings.Contains(method, "TokenExchangerService") {
			return streamer(ctx, desc, cc, method, opts...)
		}
		token, err := minter.getToken()
		if err != nil {
			return nil, fmt.Errorf("obtaining bearer token: %w", err)
		}
		ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token)
		return streamer(ctx, desc, cc, method, opts...)
	}
}
